use crate::cross_chain::rlp_decoder::RlpDecoder;
use std::time::{Duration, Instant};

#[test]
fn test_single_quote_decode_performance() {
    let encoded_data = "";

    let start = Instant::now();
    let result = RlpDecoder::decode_cross_chain_data(encoded_data);
    let duration = start.elapsed();

    assert!(result.is_ok());
    assert!(
        duration < Duration::from_millis(10),
        "Single decode should take less than 10ms, took: {duration:?}"
    );

    println!("Single quote decode time: {duration:?}");
}

#[test]
fn test_high_frequency_decode_performance() {
    let encoded_data = "";

    let iterations = 1000;
    let start = Instant::now();

    for _ in 0..iterations {
        let result = RlpDecoder::decode_cross_chain_data(encoded_data);
        assert!(result.is_ok());
    }

    let total_duration = start.elapsed();
    let avg_duration = total_duration / iterations;

    assert!(
        avg_duration < Duration::from_millis(5),
        "Average decode time should be under 5ms, was: {avg_duration:?}"
    );
    assert!(
        total_duration < Duration::from_secs(3),
        "1000 decodes should complete in under 3 seconds, took: {total_duration:?}"
    );

    println!("High-frequency test: {iterations} decodes in {total_duration:?}");
    println!("Average decode time: {avg_duration:?}");
    println!(
        "Throughput: {:.2} decodes/second",
        iterations as f64 / total_duration.as_secs_f64()
    );
}

#[test]
fn test_different_quote_sizes_performance() {
    let test_cases = vec![
        ("small", "f85989313030303030303030303089313030303030303030308931303030303030303084302e352566f831f82f81318831303030303030303089313030303030303030823025c0c0c030"),
        ("large", ""),
    ];

    for (size_name, data) in test_cases {
        let iterations = 500;
        let start = Instant::now();

        for _ in 0..iterations {
            let result = RlpDecoder::decode_cross_chain_data(data);
            if result.is_err() {
                continue;
            }
        }

        let duration = start.elapsed();
        let avg_time = duration / iterations;

        println!(
            "{} quote ({}KB): {} iterations in {:?}, avg: {:?}",
            size_name,
            data.len() / 1024,
            iterations,
            duration,
            avg_time
        );

        assert!(
            avg_time < Duration::from_millis(20),
            "{size_name} quotes should decode in under 20ms, took: {avg_time:?}"
        );
    }
}
